      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_device_id),
      fhir_composition.author = create('Reference') as fhir_composition_author_reference,
      fhir_composition_author_reference.reference = append('urn:uuid:', fhir_device_id),
      fhir_composition_author_reference.type = 'Device' then CdaAuthorToFhirDevice(cda_author, fhir_device, fhir_bundle) "CdaAuthorToFhirDevice";
  }; 
}

group CdaEmedAbgabeEntryRelationshipToFhir(source cda: ClinicalDocument, source cda_entryRelationship: EntryRelationship, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_medicationDispense: MedicationDispense, target fhir_medicationRequest: MedicationRequest, target fhir_bundle: Bundle) {

