                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.period as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_period -> fhir_medicationDispense_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationDispense_dosageInstruction_timing_boundsDuration then PQQuantity(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_period,fhir_medicationDispense_dosageInstruction_timing_boundsDuration);
                  // Tagesdosierung
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.doseQuantity as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_doseQuantity -> fhir_medicationDispense_dosageInstruction.doseAndRate = create('Element') as fhir_medicationDispense_dosageInstruction_doseAndRate,
                  fhir_medicationDispense_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_doseQuantity,fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity);
                  // Erstes Datum des Wochentages nach Einnahmebeginn
                  // TODO: Klären Transformation Datum zu Wochentag
                  // Tagesdosierung an EINEM Tag
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.phase as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_phase,
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_phase.value as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_phase_value -> fhir_medicationDispense_dosageInstruction_timing.event as fhir_medicationDispense_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_phase_value,fhir_medicationDispense_dosageInstruction_timing_event);

                  // Tagesdosierung an MEHREREN Tagen (z.B. Montag, Mittwoch, Freitag)
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.comp as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp then {
                    // Daten der Wochentage nach Einnahmebeginn
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp.phase as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase,
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase.value as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value -> fhir_medicationDispense_dosageInstruction_timing.event as fhir_medicationDispense_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value,fhir_medicationDispense_dosageInstruction_timing_event);
                    // Zeitraum und Periodeneinheit der Dosis
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp.period as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_period -> fhir_medicationDispense_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationDispense_dosageInstruction_timing_boundsDuration then PQQuantity(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_period,fhir_medicationDispense_dosageInstruction_timing_boundsDuration);
                  };
                };
              };

              // Split Dosing
              cda_entryRelationship_act_entryRelationship.substanceAdministration as cda_entryRelationship_act_entryRelationship_substanceAdministration where ($this.templateId.root = '1.3.6.1.4.1.19376.1.5.3.1.4.9') then {
                cda_entryRelationship_act_entryRelationship_substanceAdministration.effectiveTime as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime -> fhir_medicationDispense_dosageInstruction.timing = create('Timing') as fhir_medicationDispense_dosageInstruction_timing then {
                  // Einnahmezeitpunkt als Zeitcode
                  // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.event as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_event -> fhir_medicationDispense_dosageInstruction_timing.code as fhir_medicationDispense_dosageInstruction_timing_code then CECodeableConcept(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_event,fhir_medicationDispense_dosageInstruction_timing_code);
                  // Offset
                  // TODO: Sekunden in Minuten umrechnen, da FHIR Timing.repeat.offset in Minuten angegeben wird, CDA aber in Sekunden
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.offset as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_offset,
                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_offset.value as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_offset_value -> fhir_medicationDispense_dosageInstruction_timing.repeat as fhir_medicationDispense_dosageInstruction_timing_repeat,
                  fhir_medicationDispense_dosageInstruction_timing_repeat.offset as fhir_medicationDispense_dosageInstruction_timing_repeat_offset then INT(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_offset_value,fhir_medicationDispense_dosageInstruction_timing_repeat_offset);

                  cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime.comp as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp then {
                    // Einnahmezeitpunkt als Zeitcode
                    // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp.event as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_event -> fhir_medicationDispense_dosageInstruction_timing.code as fhir_medicationDispense_dosageInstruction_timing_code then CECodeableConcept(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_event,fhir_medicationDispense_dosageInstruction_timing_code);
                    // Offset
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp.offset as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_offset,
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_offset.value as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_offset_value -> fhir_medicationDispense_dosageInstruction_timing.repeat as fhir_medicationDispense_dosageInstruction_timing_repeat2,
                    fhir_medicationDispense_dosageInstruction_timing_repeat2.offset as fhir_medicationDispense_dosageInstruction_timing_repeat2_offset then INT(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_offset_value,fhir_medicationDispense_dosageInstruction_timing_repeat2_offset);
                    // Daten der Wochentage nach Einnahmebeginn
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp.phase as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase,
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase.value as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value -> fhir_medicationDispense_dosageInstruction_timing.event as fhir_medicationDispense_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value,fhir_medicationDispense_dosageInstruction_timing_event);
                    // Zeitraum und Periodeneinheit der Dosis
                    cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp.period as cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_period -> fhir_medicationDispense_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationDispense_dosageInstruction_timing_boundsDuration then PQQuantity(cda_entryRelationship_act_entryRelationship_substanceAdministration_effectiveTime_comp_period,fhir_medicationDispense_dosageInstruction_timing_boundsDuration);
                  };
                  // Tagesdosierung
                cda_entryRelationship_act_entryRelationship.doseQuantity as cda_entryRelationship_act_entryRelationship_doseQuantity -> fhir_medicationDispense_dosageInstruction.doseAndRate = create('Element') as fhir_medicationDispense_dosageInstruction_doseAndRate,
                fhir_medicationDispense_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_entryRelationship_act_entryRelationship_doseQuantity,fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity);
                };
              };
           }:
        };
    };

    // Therapieart (1.2.40.0.34.11.8.1.3.4)
    cda_entryRelationship as cda_entryRelationship where ($this.typeCode = 'COMP') then {
      cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act where ($this.templateId.root = '1.2.40.0.34.11.8.1.3.4') then {
        cda_entryRelationship_act_entryRelationship_act.code as cda_entryRelationship_act_entryRelationship_act_code -> fhir_medicationDispense.note = create('Annotation') as fhir_medication_usageInstruction then {
          cda_entryRelationship_act_entryRelationship_act_code.code as cda_entryRelationship_act_entryRelationship_act_code_code -> fhir_medication_usageInstruction.text = (cda_entryRelationship_act_entryRelationship_act_code_code) then {
            cda_entryRelationship_act_entryRelationship_act_code.originalText as cda_entryRelationship_act_entryRelationship_act_code_originalText -> fhir_medication_usageInstruction.text = append(cda_entryRelationship_act_entryRelationship_act_code_code + ' | ', cda_entryRelationship_act_entryRelationship_act_code);
          };
        };
      };
    };
}


group CdaEmedAbgabeSupplyReferenceToFhir(source cda_supply_reference: CDAReference, target fhir_medicationRequest: MedicationRequest) {

  // ID des VerordnungEntry-Containers (1.2.40.0.10.1.4.3.4.2.1)
  cda_supply_reference as cda_reference where ($this.typeCode = 'XCRPT') then {
    cda_reference.externalDocument as cda_reference_externalDocument then {
      cda_reference_externalDocument.id as cda_entryRelationship_reference_externalDocument_id -> fhir_medicationRequest.identifier = create('Identifier') as fhir_medicationRequest_identifier then II(cda_entryRelationship_reference_externalDocument_id,fhir_medicationRequest_identifier);
    };
  };
}


// --------------------------------------Verordnung-----------------------------------------------

group CdaEmedVerordnungEntryToFhir(source cda: ClinicalDocument, source cda_sbadm: SubstanceAdministration, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {

  cda_sbadm ->
    // create MedicationRequest
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('MedicationRequest') as fhir_medicationRequest,
    fhir_medicationRequest.meta as fhir_medicationRequest_meta,
    fhir_medicationRequest_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medicationrequest',
    fhir_medicationRequest.id = uuid() as fhir_medicationRequest_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_medicationRequest_id),

    // create Medication
    fhir_bundle.entry as fhir_bundle_entry2,
    fhir_bundle_entry2.resource = create('Medication') as fhir_medication,
    fhir_medication.meta as fhir_medication_meta,
    fhir_medication_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medication',
    fhir_medication.id = uuid() as fhir_medication_id,
    fhir_bundle_entry2.fullUrl = append('urn:uuid:', fhir_medication_id),

    // link Medication to MedicationRequest via medicationReference
    fhir_medicationRequest.medicationReference = create('Reference') as fhir_medicationRequest_medicationReference_reference,
    fhir_medicationRequest_medicationReference_reference.reference = append('urn:uuid:', fhir_medication_id),
    fhir_medicationRequest_medicationReference_reference.type = 'Medication' then {

      // map consumable -> Medication
      cda_sbadm.consumable as cda_consumable then CdaEmedConsumableToFhirMedication(cda, cda_consumable, fhir_composition, fhir_medication, fhir_patient, fhir_bundle);

      // author
      cda_sbadm.author as cda_author then CdaEmedVerordnungSbadmAuthorToFhir(cda, cda_author, fhir_composition, fhir_medication, fhir_medicationRequest, fhir_bundle);
    };
}

group CdaEmedConsumableToFhirMedication(source cda: ClinicalDocument, source cda_consumable: Consumable, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_patient: Patient, target fhir_bundle: Bundle) {
    
    cda_consumable then {

      // fill FHIR Medication resource with information from CDA consumable of Verordnung-Entry
      cda_consumable.manufacturedProduct as cda_manufacturedProduct then {
        cda_manufacturedProduct.manufacturedMaterial as cda_manufacturedMaterial -> fhir_medication.code = create('CodeableConcept') as fhir_medication_code then {

          cda_manufacturedMaterial.code as cda_manufacturedMaterial_code then {

            // PZN aus Hauptcode
            // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code
            // -> Medication.code.coding (PZN)
            cda_manufacturedMaterial_code where ($this.codeSystem = '1.2.40.0.34.4.16') ->
              fhir_medication_code.coding = create('Coding') as fhir_medication_code_coding then
                CECoding(cda_manufacturedMaterial_code, fhir_medication_code_coding);

            // Zulassungsnummer aus translation
            // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code/translation
            // -> Medication.code.coding (Zulassungsnummer)
            cda_manufacturedMaterial_code.translation as cda_manufacturedMaterial_code_translation where ($this.codeSystem = '1.2.40.0.34.4.17') ->
              fhir_medication_code.coding = create('Coding') as fhir_medication_code_coding_translation then
                CECoding(cda_manufacturedMaterial_code_translation, fhir_medication_code_coding_translation);
          };

          // Name
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/name
          // -> Medication.code.text
          cda_manufacturedMaterial.name -> fhir_medication_code.text;

          // Darreichungsform
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/formCode
          // -> Medication.form
          cda_manufacturedMaterial.formCode -> fhir_medication.form;

          // Packungsgröße
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/asContent/containerPackagedMedicine/capacityQuantity
          // -> Medication.amount
          cda_manufacturedMaterial.asContent as cda_asContent then {
            cda_asContent.containerPackagedMedicine as cda_containerPackagedMedicine then {
              cda_containerPackagedMedicine.capacityQuantity as capq ->
                fhir_medication.amount = create('Ratio') as fhir_medication_amount then {
                  capq -> fhir_medication_amount.numerator = create('Quantity') as fhir_medication_amount_numerator then
                    PQQuantity(capq, fhir_medication_amount_numerator);

                  capq -> fhir_medication_amount.denominator = create('Quantity') as fhir_medication_amount_denominator,
                  fhir_medication_amount_denominator.value = '1',
                  fhir_medication_amount_denominator.unit = 'Packung';
                };
            };
          };

          // Wirkstoffe
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/ingredient
          // -> Medication.ingredient
          cda_manufacturedMaterial.ingredient as cda_ingredient then {
            cda_ingredient.ingredient as cda_ingredient_inner ->
              fhir_medication.ingredient as fhir_medication_ingredient then {

                cda_ingredient_inner ->
                  fhir_medication_ingredient.item = create('CodeableConcept') as fhir_medication_ingredient_item then {

                    // Name
                    cda_ingredient_inner.name -> fhir_medication_ingredient_item.text;

                    cda_ingredient_inner.code as cda_ingredient_inner_code then {
                      // ATC / Hauptcode
                      cda_ingredient_inner_code where ($this.codeSystem = '2.16.840.1.113883.6.73') ->
                        fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding then
                          CECoding(cda_ingredient_inner_code, fhir_medication_ingredient_item_coding);

                      // AGES Wirkstoff
                      cda_ingredient_inner_code where ($this.codeSystem = '1.2.40.0.34.5.156') ->
                        fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding2 then
                          CECoding(cda_ingredient_inner_code, fhir_medication_ingredient_item_coding2);

                      // translation, z.B. atc-deutsch-wido
                      cda_ingredient_inner_code.translation as cda_ingredient_inner_code_translation where ($this.codeSystem = '1.2.276.0.76.5.558') ->
                        fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding3 then
                          CECoding(cda_ingredient_inner_code_translation, fhir_medication_ingredient_item_coding3);
                    };
                };
            };
          };
        };
      };
    };
}

group CdaEmedVerordnungSbadmAuthorToFhir(source cda: ClinicalDocument, source cda_author: Author, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_medicationRequest: MedicationRequest, target fhir_bundle: Bundle) {

  // Author is Person -> map to PractitionerRole and Practitioner
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedPerson.exists()) then {

      // Date of prescription
      cda_author.time -> fhir_medicationRequest.authoredOn;

      // create FHIR PractitionerRole resource for the assignedAuthor
      cda_author_assignedAuthor -> fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('PractitionerRole') as fhir_practitionerRole,
      fhir_practitionerRole.meta as fhir_practitionerRole_meta,
      fhir_practitionerRole_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-practitionerrole',
      fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),

      // link PractitionerRole to MedicationRequest as requester
      fhir_medicationRequest.requester = create('Reference') as fhir_medicationRequest_requester_reference,
      fhir_medicationRequest_requester_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_medicationRequest_requester_reference.type = 'PractitionerRole',

      // create Practitioner
      fhir_bundle.entry as fhir_bundle_entry2,
      fhir_bundle_entry2.resource = create('Practitioner') as fhir_practitioner,
      fhir_practitioner.meta as fhir_practitioner_meta,
      fhir_practitioner_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-practitioner',
      fhir_practitioner.id = uuid() as fhir_practitioner_id,
      fhir_bundle_entry2.fullUrl = append('urn:uuid:', fhir_practitioner_id),

      // link Practitioner to PractitionerRole
      fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
      fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
      fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then
        CdaAuthorToFhirPractitionerAndPractitionerRole(cda_author, fhir_practitioner, fhir_practitionerRole, fhir_bundle) "CdaAuthorToFhirPractitionerAndPractitionerRole";
  };

  // Author is Device -> map to Device
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedAuthoringDevice.exists()) then {

      // Date of prescription
      cda_author.time -> fhir_medicationRequest.authoredOn;

      // create FHIR Device resource for the assignedAuthor
      cda_author_assignedAuthor -> fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Device') as fhir_device,
      fhir_device.meta as fhir_device_meta,
      fhir_device_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-device',
      fhir_device.id = uuid() as fhir_device_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_device_id),

      // link Device to MedicationRequest as requester
      fhir_medicationRequest.requester = create('Reference') as fhir_medicationRequest_requester_reference,
      fhir_medicationRequest_requester_reference.reference = append('urn:uuid:', fhir_device_id),
      fhir_medicationRequest_requester_reference.type = 'Device' then
        CdaAuthorToFhirDevice(cda_author, fhir_device, fhir_bundle) "CdaAuthorToFhirDevice";
  };
}

group CdaEmedVerordnungSupplyEntryToFhir(source cda_author: Author, target fhir_composition: Composition, target fhir_medicationRequest: MedicationRequest, target fhir_bundle) {
}